using System.IO;
using System.Text;

namespace VirusTotalNet.ReportGenerator;

public static class ProtocolUtil
{
    private const string StyleSheetForProtocol =
        "<?xml-stylesheet type=\"text/xsl\" href=\"#stylesheet\"?>\r\n<!DOCTYPE doc [\r\n<!ATTLIST xsl:stylesheet\r\nid ID #REQUIRED>\r\n]>\r\n<doc>\r\n    <!--Start XSL-->\r\n    <xsl:stylesheet id=\"stylesheet\"\r\n    version=\"1.0\"\r\n    xmlns:xsl=\"http://www.w3.org/1999/XSL/Transform\" \r\n    xmlns:ps=\"http://schemas.microsoft.com/powershell/2004/04\"\r\n\txmlns:scanvirustotalprotocol=\"http://www.example.org/ScanVirusTotalProtocol\">\r\n    <xsl:template match=\"xsl:stylesheet\" />\r\n  \r\n    <xsl:template match=\"/doc\">\r\n    <html>\r\n    <head>\r\n        <style>      \r\n\t\t\ttable {\r\n\t\t\twidth: 100%;\r\n\t\t\tfont-family: Tahoma;\r\n\t\t\tborder-collapse: collapse;\r\n\t\t\tfont-size: 12px;\r\n\t\t\t}\r\n\t\t\ttable, th, td {\r\n\t\t\tborder: 1px solid black;\r\n\t\t\ttext-align:left;\r\n\t\t\t}\r\n\t\t\theader{\r\n\t\t\ttext-align:left;\r\n\t\t\tfont-family: Tahoma;\r\n\t\t\t}\r\n\t\t\tfooter {\r\n\t\t\ttext-align:left;\r\n\t\t\tfont-family: Tahoma;\r\n\t\t\tfont-size: 12px;\r\n\t\t\t}\r\n\t\t\t.noBorder {\r\n\t\t\tborder:none !important;\r\n\t\t\t}\r\n\t\t\ttd {\r\n\t\t\t\tborder:none !important;\t\t\r\n\t\t\t}\r\n\t\t\ttr:nth-child(2n+1) {\r\n\t\t\t\t background-color: #F5F5F5;\r\n\t\t\t}\r\n\t\t\tp.scanFile {\r\n\t\t\t\tfont-size: 12px; \r\n\t\t\t\tfont-weight: bold; \r\n\t\t\t\tfont-family: Tahoma;\r\n\t\t\t}\r\n\t\t\tspan {\r\n\t\t\t\tpadding-left:3px;\r\n\t\t\t}\r\n        </style>\r\n        <script src=\"http://ajax.googleapis.com/ajax/libs/jquery/1.9.1/jquery.min.js\"></script>\r\n    </head>\r\n    <body>\r\n\t\t<header>\r\n\t\t\t<h1>VirusTotal Report</h1>\r\n\t\t\t<xsl:variable name=\"startDate\" select=\"substring-before(ScanVirusTotalProtocol/header/startDateTime,'T')\"/>\r\n\t\t\t<xsl:variable name=\"startTime\" select=\"substring-after(ScanVirusTotalProtocol/header/startDateTime,'T')\"/>\r\n\t\t\t<p><xsl:value-of select= '$startDate'/> <span> </span> <xsl:value-of select=\"substring-before($startTime,'.')\"/> <span>[Duration]</span></p>\r\n\t\t\t<p>All scanned files: <xsl:value-of select=\"ScanVirusTotalProtocol/header/fileScannedList\"/></p>\r\n\t\t    <h3>\r\n                <span style=\"color: #000000; cursor: pointer;\" onclick=\"ShowTotal()\" onmouseout=\"this.style.textDecoration='none';\" onmouseover=\"this.style.textDecoration='underline';\">\r\n                    <xsl:value-of select=\"ScanVirusTotalProtocol/header/summaryScanCase\" />\r\n                </span>\r\n                <span>, </span>\r\n                <span style = \"color: #6AC259; cursor: pointer;\" onclick=\"ShowUndetecteds()\" onmouseout=\"this.style.textDecoration='none';\" onmouseover=\"this.style.textDecoration='underline';\">\r\n                    <xsl:value-of select=\"ScanVirusTotalProtocol/header/scanCaseUndetected\" />\r\n                </span>\r\n                <span>, </span>\r\n                <span style = \"color: #eab765; cursor: pointer;\" onclick=\"ShowDetecteds()\" onmouseout=\"this.style.textDecoration='none';\" onmouseover=\"this.style.textDecoration='underline';\">\r\n                    <xsl:value-of select=\"ScanVirusTotalProtocol/header/scanCaseDetected\" />\r\n                </span>\r\n            </h3>\r\n        </header>\r\n\t\t<footer>\r\n\t\t    <h2 id=\"Total\" style=\"display:none\">Total</h2>\r\n            <table id=\"TableTotal\">\r\n                <tr><th>No</th><th>Engine name</th><th>Result</th><th>Date updated</th></tr>\r\n                <xsl:for-each select=\"ScanVirusTotalProtocol/scanFile/ScanFile/scanSteps/ScanStepsScanStep\">\r\n                <tr>\r\n                    <td><xsl:value-of select=\"position()\"/></td>\r\n                    <td><xsl:value-of select=\"toolAntivirus\"/></td>\r\n                    <td><xsl:value-of select=\"vesion\"/></td>\r\n                    <td><xsl:value-of select=\"updateDate\"/></td>\r\n                </tr>\r\n                </xsl:for-each>\r\n            </table>\r\n\t\t    <h2 id=\"Undetected\" style=\"display:none\">Undetected</h2>\r\n            <table id=\"TableUndetected\">\r\n                <tr><th>No</th><th>Engine name</th><th>Result</th><th>Date updated</th></tr>\r\n                <xsl:for-each select=\"ScanVirusTotalProtocol/scanFile/ScanFile/scanSteps/ScanStepsScanStep[result='Undetected']\">\r\n                <tr>\r\n                    <td><xsl:value-of select=\"position()\"/></td>\r\n                    <td><xsl:value-of select=\"toolAntivirus\"/></td>\r\n                    <td><xsl:value-of select=\"vesion\"/></td>\r\n                    <td><xsl:value-of select=\"updateDate\"/></td>\r\n                </tr>\r\n                </xsl:for-each>\r\n            </table>\r\n\t\t    <h2 id=\"Detected\" style=\"display:none\">Detected</h2>\r\n            <table id=\"TableDetected\">\r\n                <tr><th>No</th><th>Engine name</th><th>Result description</th><th>Result</th><th>Date updated</th></tr>\r\n                <xsl:for-each select=\"ScanVirusTotalProtocol/scanFile/ScanFile/scanSteps/ScanStepsScanStep[result='Detected']\">\r\n                <tr>\r\n                    <td><xsl:value-of select=\"position()\"/></td>\r\n                    <td><xsl:value-of select=\"toolAntivirus\"/></td>\r\n                    <td><xsl:value-of select=\"resultDescription\"/></td>\r\n                    <td><xsl:value-of select=\"result\"/></td>\r\n                    <td><xsl:value-of select=\"updateDate\"/></td>\r\n                </tr>\r\n                </xsl:for-each>\r\n            </table>\r\n        </footer>\r\n\t\t<hr/>\r\n        <div>\r\n            <p style=\"font-size:12px; font-family: Tahoma;\">Short Name: <span><xsl:value-of select=\"ScanVirusTotalProtocol/header/shortName\"/></span></p>\r\n            <p style=\"font-size:12px; font-family: Tahoma;\">File List: <span><xsl:value-of select=\"ScanVirusTotalProtocol/header/fileList\"/></span></p>\r\n            <p style=\"font-size:12px; font-family: Tahoma;\">Execution Time: <span><xsl:value-of select=\"ScanVirusTotalProtocol/header/executionTime\"/></span></p>\r\n        </div>\r\n        <script>\r\n            function ShowTotal()\r\n            {\r\n                document.getElementById(\"Total\").style.display=\"block\";\r\n                document.getElementById(\"Undetected\").style.display=\"none\";\r\n                document.getElementById(\"Detected\").style.display=\"none\";\r\n            }\r\n            function ShowUndetecteds()\r\n            {\r\n                document.getElementById(\"Total\").style.display=\"none\";\r\n                document.getElementById(\"Undetected\").style.display=\"block\";\r\n                document.getElementById(\"Detected\").style.display=\"none\";\r\n            }\r\n            function ShowDetecteds()\r\n            {\r\n                document.getElementById(\"Total\").style.display=\"none\";\r\n                document.getElementById(\"Undetected\").style.display=\"none\";\r\n                document.getElementById(\"Detected\").style.display=\"block\";\r\n            }\r\n        </script>\r\n    </body>\r\n    </html>\r\n    </xsl:template>\r\n    </xsl:stylesheet>";

    public static string GetTotalInformationTestProtocol(string executionTime)
    {
        var sb = new StringBuilder(StyleSheetForProtocol);
        sb.Replace("[Duration]", "<span>(Duration " + executionTime + "), </span>");
        return sb.ToString();
    }

    public static void AddStyleSheetForProtocol(string pathFile, string styleSheet)
    {
        if (!File.Exists(pathFile)) return;

        var lines = File.ReadAllLines(pathFile).ToList();
        lines.Insert(1, styleSheet);
        lines.Insert(lines.Count, "</doc>");
        File.WriteAllLines(pathFile, lines.ToArray());
    }
}